def suggestions() -> str:
    cards = []
    for p in DATA['proposals']:
        refs = ' · '.join(f'<a href="#{qid}">{qid}</a>' for qid in p['evidence_needed'])
        cards.append(f'''<article class="p26-proposal" data-proposal data-priority="{p['priority']}"><div class="p26-proposal-top"><span class="p26-status">{esc(p['priority'])} · {esc(p['area'])}</span><span>{p['id']}</span></div><h3>{esc(p['title'])}</h3><p>{esc(p['why'])}</p><p><strong>Next discovery step:</strong> {esc(p['next'])}</p><p class="p26-fine">Evidence to close: {refs}<br>Basis: {source_link(p['source'])}</p><label for="decision-{p['id']}">Your review <span>(does not implement changes)</span></label><select id="decision-{p['id']}" data-decision-id="{p['id']}"><option value="unreviewed">Not reviewed</option><option value="shortlist">Shortlist for next review</option><option value="defer">Defer until evidence arrives</option><option value="reject">Do not pursue</option></select></article>''')

    paths = []
    for p in DATA['paths']:
        needs = ' · '.join(f'<a href="#{q}">{q}</a>' for q in p['needs']) or 'Nothing external — this one is a build decision, not an evidence request.'
        ribbon = '<span class="p26-ribbon">In the recommended order</span>' if p['recommended'] else ''
        changes = ''.join(f'<li>{esc(x)}</li>' for x in p['changes'])
        paths.append(f'''<article class="p26-path" data-path><div class="p26-path-top"><p class="p26-overline">PATH {p['sequence']:02d}</p>{ribbon}</div><h3>{esc(p['name'])}</h3><p class="p26-path-pitch">{esc(p['pitch'])}</p><div class="p26-path-grid"><div><p class="p26-overline">WHAT A READER WOULD SEE</p><ul>{changes}</ul></div><div class="p26-path-facts"><p class="p26-overline">NEEDS FIRST</p><p>{needs}</p><p class="p26-overline">WHAT IT UNBLOCKS</p><p>{esc(p['unblocks'])}</p><p class="p26-overline">WHAT IT CANNOT DELIVER</p><p>{esc(p['cannot'])}</p><p class="p26-overline">COST / RISK</p><p>{esc(p['cost'])}<br>{esc(p['risk'])}</p></div></div><p class="p26-fine">Basis: {source_link(p['basis'])} · Gate status: <span class="p26-status">{esc(p['status'])}</span></p><label for="decision-{p['id']}">Your review <span>(choosing a path here implements nothing)</span></label><select id="decision-{p['id']}" data-decision-id="{p['id']}"><option value="unreviewed">Not reviewed</option><option value="shortlist">Take this path next</option><option value="defer">Defer until evidence arrives</option><option value="reject">Do not pursue</option></select></article>''')
    ordered = sorted(DATA['paths'], key=lambda x: x['sequence'])
    now_ids = ' → '.join(f"PATH {p['sequence']:02d}" for p in ordered if p['recommended'])
    later = ' · '.join(esc(p['name']) for p in ordered if not p['recommended'])
    sequence_note = f'''<div class="p26-sequence"><p class="p26-overline">THE ORDER WE WOULD WORK IN, AND WHY</p><p><strong>{now_ids}</strong> — polish the shop, prove the links, then switch on measurement. <strong>Then decide:</strong> {later}. The first path needs nothing from anyone; the next two are stopped by account and hosting decisions, and the last two are stopped by evidence and budget. Choosing here records a preference in this browser; it starts no work.</p></div>'''

    rows = []
    for q in DATA['questions']:
        rows.append(f'<tr id="{q["id"]}"><th scope="row"><small>{q["id"]}</small><br>{esc(q["question"])}</th><td>{esc(q["known"])}</td><td>{esc(q["missing"])}</td><td><span class="p26-owner">{esc(q.get("answer_by", "Owner"))}</span><br><small>{esc(q.get("answer_form", ""))}</small></td><td>{esc(q["discovery"])}</td><td>{esc(q["default"])}</td><td>{source_link(q["source"])}</td></tr>')

    intake = DATA['suggestion_intake']
    intake_rows = ''.join(f'<div class="p26-intake-row"><dt>{esc(field)}</dt><dd>{esc(hint)}</dd></div>' for field, hint in intake['fields'])

    blocks = []
    for block in DATA['design_prompt']['blocks']:
        bid = f'prompt-{block["id"]}'
        blocks.append(f'''<div class="p26-prompt-block" id="{bid}"><div class="p26-prompt-head"><h3>{esc(block['heading'])}</h3><button type="button" class="p26-text-button" data-copy-from="{bid}">Copy this block</button></div><p>{esc(block['text'])}</p><p class="p26-fine">Basis: {source_link(block['basis'])}</p></div>''')

    body = f'''<div class="p26-container"><div class="p26-page-intro"><p class="p26-overline">BEHIND THE SITE / SUGGESTIONS &amp; DECISIONS</p><h1>A good next step<br><em>starts with the evidence.</em></h1><p>Choose a path, see what is missing, and leave an honest note about it — without accidentally implementing anything.</p></div><div class="p26-review-note"><strong>Review mode only.</strong> Choices are saved only when you press Save, in this browser. They do not publish pages, spend money, change accounts or activate tracking. Both the paths and the individual proposals are included in what you save and export. <a href="../suggestions.html">Open the full historical suggestions register</a>.</div><section class="p26-section" id="paths"><div class="p26-section-heading"><div><p class="p26-overline">{len(DATA['paths'])} PATHS, ONE DECISION AT A TIME</p><h2>Pick a direction, not a feature.</h2></div></div><p class="p26-section-dek">Each path is a bundle of the smaller proposals below, with its dependencies named: what it needs before it can be done honestly, what it buys the reader, and what it still cannot claim afterwards.</p>{sequence_note}<div class="p26-paths-grid">{''.join(paths)}</div></section><section class="p26-section" id="proposals"><div class="p26-section-heading"><div><p class="p26-overline">{len(DATA['proposals'])} PROPOSALS, {len(DATA['questions'])} OPEN QUESTIONS</p><h2>Choose what deserves the next look.</h2></div></div><div class="p26-filter-row" role="group" aria-label="Filter suggestions"><button type="button" class="p26-filter is-active" data-proposal-filter="all" aria-pressed="true">All suggestions</button><button type="button" class="p26-filter" data-proposal-filter="Now" aria-pressed="false">Now</button><button type="button" class="p26-filter" data-proposal-filter="Next" aria-pressed="false">Next</button><button type="button" class="p26-filter" data-proposal-filter="Later" aria-pressed="false">Later</button></div><div class="p26-proposals-grid">{''.join(cards)}</div><div class="p26-review-actions"><button type="button" class="p26-button" data-save-review>Save this review {icon('check')}</button><button type="button" class="p26-button p26-button-outline" data-export-review>Export review JSON</button><button type="button" class="p26-text-button" data-reset-review>Clear saved choices</button><p id="p26-review-status" role="status" aria-live="polite">No changes will be implemented from this page.</p></div><noscript><p>JavaScript is off. You can still read every path, suggestion and evidence question; saving and exporting a local review require JavaScript.</p></noscript></section><section class="p26-section" id="questions"><p class="p26-overline">THE DECISION-READINESS REGISTER</p><h2>What do we know? Who holds the rest?</h2><p>Every open question in one table, with the answer as far as it exists, the person or system who can actually supply the rest, and what a complete answer would look like. These are unanswered operational questions, not an invitation to invent answers. Where a fact cannot be confirmed from an official source it is left blank and flagged. Official references explain the applicable rule or context; repository status and safe defaults are our own observations, not certifications by those third parties.</p><div class="p26-table-scroll" tabindex="0" role="region" aria-label="Decision questions, answer owners, evidence gaps and discovery actions"><table class="p26-table p26-question-table"><thead><tr><th scope="col">Question</th><th scope="col">Known / answer so far</th><th scope="col">Missing information</th><th scope="col">Who can answer · what counts as an answer</th><th scope="col">How to discover it</th><th scope="col">Safe default</th><th scope="col">Official basis</th></tr></thead><tbody>{''.join(rows)}</tbody></table></div></section><section class="p26-section" id="intake"><div class="p26-intake"><div><p class="p26-overline">HOW TO ADD ONE</p><h2>{esc(intake['title'])}</h2><p>{esc(intake['note'])}</p></div><dl class="p26-intake-list">{intake_rows}</dl></div></section><section class="p26-section" id="design-prompt"><p class="p26-overline">THE NEXT DESIGN BRIEF</p><h2>A prompt worth building from.</h2><p>{esc(DATA['design_prompt']['intro'])} It is a proposed direction grounded in the limits above — not an instruction to treat missing evidence as confirmed.</p><div class="p26-prompt" id="p26-design-prompt">{''.join(blocks)}</div><div class="p26-prompt-actions"><button type="button" class="p26-button p26-button-outline" data-copy-prompt>Copy the whole brief</button><span id="p26-copy-status" role="status"></span></div></section><section class="p26-section"><h2>The publishing gate.</h2><ol class="p26-pipeline"><li><strong>Discover</strong><span>Use authorized first-party inputs. Keep provenance and capture date.</span></li><li><strong>Draft</strong><span>Question-led, source-linked copy. Missing facts stay absent.</span></li><li><strong>Check</strong><span>Disclosures, sponsored links, intent, API permissions, unsupported claims, feed and sitemap.</span></li><li><strong>Approve</strong><span>Require real evidence and account authority for gated capabilities.</span></li><li><strong>Measure</strong><span>Use real query, click and report evidence—not forecasts—to choose the next question.</span></li></ol></section></div>'''
    return shell(
        'suggestions/index.html',
        'Suggestions, missing information and decision review',
        f'Review {len(DATA["paths"])} paths and {len(DATA["proposals"])} proposals against {len(DATA["questions"])} open questions, each with its answer owner, discovery action and safe default, plus a {len(DATA["design_prompt"]["blocks"])}-block design brief. Saving a review never implements changes.',
        body,
    )
